INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('f75b8079-8b74-4a7d-b250-c3e7b88ced2b', 'c1c2c3d4-3030-4000-8000-000000000030', 1, 'Perceber', 'Semana 1 — Despertar', '{"pch": "A pressa revela\u2026 onde a confian\u00e7a ainda n\u00e3o chegou.", "verse": "Mt 6,25-34", "lectio": "Leia o texto lentamente. Pare na palavra que incomoda. Pergunte: por que essa palavra me toca?", "practice": "Escreva no di\u00e1rio: qual \u00e1rea da minha vida estou tentando controlar com pressa?", "question": "O que est\u00e1 te acelerando?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;